// Durable execution is separate from editable design drafts and the browser-only history.
const executionCache=new Map();let executionLoading=false,executionError='',executionBusy=false;
let activeBatchId='';
function executionData(){return executionCache.get(taskId)||{batches:[],issues:[],reports:[]}}
function currentBatch(){const d=executionData();return d.batches.find(b=>b.id===activeBatchId)||d.batches.at(-1)}
async function loadExecution(id=taskId){if(executionLoading)return;executionLoading=true;executionError='';try{executionCache.set(id,await workspaceRequest('/api/execution/'+encodeURIComponent(id)))}catch(e){executionError=e.message}finally{executionLoading=false;render()}}
async function executionWrite(action,raw){
 if(executionBusy)return;
 executionBusy=true;const owner=taskId;
 const submit=$('#modalSubmit');if(submit)submit.disabled=true;
 try{await flushWorkspace();const result=await workspaceRequest('/api/execution/'+action,raw,30000);executionOverview=null;if(action==='create')activeBatchId=result.id;closeModal();await loadExecution(owner);toast('已保存到本地后台');return result}
 catch(e){toast(e.message)}finally{executionBusy=false;if(submit)submit.disabled=false}
}
const legacyExecution=execution;
execution=function(){
 if(!['manual','issues','change'].includes(journey))return legacyExecution();
 const d=executionData(),b=currentBatch();
 return `<div class="card pad"><div class="row"><div><h2>手工执行批次</h2><p class="subtitle">每个批次固定用例、资料、环境和产品版本。重试保留每次尝试。</p></div><div class="actions">${btn('刷新','executionRefresh','small')}${btn('新建执行批次','batchNew','primary')}</div></div>${executionError?`<p role="alert">${esc(executionError)}</p>`:''}<div class="tags">${d.batches.map(x=>btn(x.name+(x.status==='closed'?' · 已结束':''),'batchSelect:'+x.id,x.id===b?.id?'primary small':'small')).join('')}</div></div>`+
 (!b?`<div class="card empty">${executionLoading?'正在加载执行记录…':'还没有执行批次。先确认用例，再新建批次。历史示例结果仍在“执行与报告”中，不计入新批次。'}</div>`:
 `<div class="card pad"><div class="row"><div><h3>${esc(b.name)}</h3><p>环境：${esc(b.environment)} · 产品版本：${esc(b.productVersion)} · ${b.cases.length} 条用例</p><p class="subtitle">${esc(b.createdAt)} · ${b.status==='open'?'执行中':'已结束'}</p></div>${b.status==='open'?btn('结束批次','batchClose','small'):btn('冻结报告','reportFreeze','primary small')}</div>${b.conclusion?`<p>${esc(b.conclusion)}</p>`:''}</div><div class="card table-wrap"><table><thead><tr><th>用例快照</th><th>最近结果</th><th>尝试次数</th><th>操作</th></tr></thead><tbody>${b.cases.map(c=>{const a=b.attempts.filter(a=>a.caseId===c.id);return `<tr><td>${esc(c.title)}<small>${esc(c.id)}</small></td><td>${badge(a.at(-1)?.result||'未执行')}</td><td>${a.length}</td><td>${b.status==='open'?btn('录入结果','batchRecord:'+c.id,'small'):''}${btn('查看历史','batchHistory:'+c.id,'link small')}</td></tr>`}).join('')}</tbody></table></div>`);
};
function evidenceLinks(a){return(a.evidence||[]).map(f=>`<a href="/api/evidence/${f.id}" download="${esc(f.name)}">${esc(f.name)}</a> <small>SHA256 ${esc(f.sha256.slice(0,12))}</small>`).join('<br>')}
function frozenText(r){return `测试报告 · ${r.batch.taskName}\n报告修订：${r.revision} · ${r.frozenAt}\n需求单号：${r.batch.requirementNo||'未填写'}\n批次：${r.batch.name}\n产品版本：${r.batch.productVersion}\n环境：${r.batch.environment}\n\n独立用例 ${r.caseCount} / 执行项 ${r.executionItemCount} / 尝试 ${r.attemptCount}\n${Object.entries(r.counts).map(([k,v])=>k+'：'+v).join('；')}\n失败后重试通过：${r.retryPassedCount}\n需求覆盖率：N/A（尚未建立完整需求分母）\n未关闭问题：${r.issues.filter(i=>i.status!=='已关闭').length}\n\n批次结论：${r.batch.conclusion}\n未测范围与遗留风险：${r.notes}\n\n${r.batch.cases.map(c=>{const aa=r.batch.attempts.filter(a=>a.caseId===c.id);return c.id+' '+c.title+'\n'+aa.map(a=>a.at+' '+a.result+' '+a.actual+(a.evidence.length?'\n证据：'+a.evidence.map(f=>f.name+' SHA256 '+f.sha256).join('；'):'')).join('\n')}).join('\n\n')}\n\n统计仅包含本批次手工记录，不含自动化模拟；本报告不代表发布批准。`}
const priorSummary=summary;
summary=function(){const d=executionData();return `<div class="card pad"><h2>冻结报告</h2><p class="subtitle">结束批次后，在手工执行页面冻结报告；后续问题处理不改写旧报告，可再次冻结形成新修订。</p>${d.reports.map(r=>`<div class="list-item row"><div><b>${esc(r.batch.name)} · 修订 ${r.revision}</b><p>${esc(r.frozenAt)} · ${r.attemptCount} 次尝试</p></div>${btn('查看 / 导出','frozenView:'+r.id,'small')}</div>`).join('')||'<p>暂无冻结报告。</p>'}${btn('进入手工执行','direct:manual:'+taskId,'small')}</div><details><summary>旧版草稿总结与示例记录（独立统计）</summary>${priorSummary()}</details>`};
const priorIssues=issues;
issues=function(){const d=executionData();return `<div class="card pad"><h2>执行问题</h2><p class="subtitle">同一批次同一用例的未关闭问题合并后续失败；重试通过不会自动关闭。</p>${d.issues.map(i=>`<div class="list-item row"><div><b>${esc(i.title)}</b><p>${esc(i.type)} · ${esc(i.status)} · ${i.attemptIds.length} 次失败/阻塞</p></div>${btn('处理问题','executionIssue:'+i.id,'small')}</div>`).join('')||'<p>暂无新执行问题。</p>'}</div><details><summary>旧版问题记录</summary>${priorIssues()}</details>`};
const executionAct=act;
act=function(action){
 const [name,id]=action.split(':'),t=task(),b=currentBatch();
 if(name==='executionRefresh')return loadExecution();
 if(name==='batchSelect'){activeBatchId=id;render();return}
 if(name==='batchNew')return modal('新建测试套件',`<label>套件名称<input name="name" required maxlength="100" value="${esc(t.name)} · 手工验证"></label><div class="form-grid"><label>产品版本<input name="productVersion" required maxlength="100" value="${esc(t.version)}"></label><label>执行环境<input name="environment" required maxlength="200" value="${esc(t.environment||'')}" placeholder="填写实际环境名称或地址"></label></div><h3>选择已确认用例</h3>${t.cases.filter(c=>c.confirmed&&!c.reviewNeeded).map(c=>`<label class="inline-check"><input class="check" type="checkbox" name="caseIds" value="${esc(c.id)}" checked>${esc(c.title)}</label>`).join('')||'<p>没有可执行的已确认用例。</p>'}`,'创建套件',f=>{executionWrite('create',{taskId:t.id,name:f.get('name'),productVersion:f.get('productVersion'),environment:f.get('environment'),caseIds:f.getAll('caseIds')});return false});
 if(name==='batchRecord'){
  const c=b.cases.find(c=>c.id===id),requestId=crypto.randomUUID();
  return modal('录入手工执行结果',`<h3>${esc(c.title)}</h3><pre class="spec-preview">${esc(c.steps)}\n\n预期：${esc(c.expected)}</pre><label>结果<select name="result"><option>通过</option><option>失败</option><option>阻塞</option><option>跳过</option></select></label><label>实际结果 / 原因<textarea name="actual" maxlength="10000"></textarea></label><label>证据文件<input id="attemptFiles" type="file" multiple accept=".png,.jpg,.jpeg,.txt,.log,.json"></label><p class="subtitle">最多 3 份，每份 2 MB。上传保存原文件，请勿附带密码或访问凭据。</p>`,'保存执行尝试',f=>{if(executionBusy)return false;const files=[...$('#attemptFiles').files];if(files.length>3||files.some(x=>x.size>2*1024*1024)){toast('最多 3 份文件，每份不超过 2 MB');return false}$('#modalSubmit').disabled=true;Promise.all(files.map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,base64:reader.result.split(',')[1]});reader.onerror=reject;reader.readAsDataURL(file)}))).then(files=>executionWrite('record',{batchId:b.id,caseId:id,requestId,result:f.get('result'),actual:f.get('actual'),files})).catch(()=>{toast('证据读取失败');$('#modalSubmit').disabled=false});return false});
 }
 if(name==='batchHistory')return modal('用例执行历史',`${b.attempts.filter(a=>a.caseId===id).map(a=>`<div class="list-item"><b>${esc(a.at)} · ${esc(a.result)}</b><p>${esc(a.actual)}</p><p>${evidenceLinks(a)}</p><small>${esc(a.id)}</small></div>`).join('')||'<p>尚未执行。</p>'}`,'关闭',()=>{});
 if(name==='batchClose')return modal('结束执行批次','<p>结束后不能继续追加尝试。未执行项目保留“未执行”，后续回归请新建批次。</p><label>本轮结论<textarea name="conclusion" required maxlength="4000"></textarea></label>','结束批次',f=>{executionWrite('close',{batchId:b.id,conclusion:f.get('conclusion')});return false});
 if(name==='reportFreeze')return modal('冻结报告','<label>未测范围、遗留风险和结论依据<textarea name="notes" required maxlength="4000"></textarea></label><p>冻结报告保留当前全部尝试与问题状态；不能修改旧修订。</p>','生成冻结报告',f=>{executionWrite('freeze',{batchId:b.id,notes:f.get('notes')}).then(r=>{if(r){journey='summary';tab='summary';render()}});return false});
 if(name==='frozenView'){const r=executionData().reports.find(r=>r.id===id);return modal('冻结报告 · 修订 '+r.revision,`<pre class="spec-preview">${esc(frozenText(r))}</pre><div class="actions">${btn('导出文本','frozenText:'+id,'small')}${btn('导出 HTML','frozenHtml:'+id,'small')}${btn('导出 JSON 快照','frozenJson:'+id,'small')}</div>`,'关闭',()=>{})}
 if(['frozenText','frozenHtml','frozenJson'].includes(name)){const r=executionData().reports.find(r=>r.id===id);const text=frozenText(r);if(name==='frozenText')download(r.id+'.txt',text,'text/plain');if(name==='frozenJson')download(r.id+'.json',JSON.stringify(r,null,2),'application/json');if(name==='frozenHtml')download(r.id+'.html','<!doctype html><meta charset="utf-8"><title>测试报告</title><style>body{max-width:1000px;margin:40px auto;padding:24px;font:16px/1.7 sans-serif}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style><h1>冻结测试报告</h1><pre>'+esc(text)+'</pre>','text/html');return}
 if(name==='executionIssue'){const i=executionData().issues.find(i=>i.id===id),batch=executionData().batches.find(b=>b.id===i.batchId);return modal('处理执行问题',`<h3>${esc(i.title)}</h3><label>分类<select name="type">${['待分类','产品缺陷','环境问题','用例问题','数据问题','需求疑问'].map(s=>`<option ${i.type===s?'selected':''}>${s}</option>`).join('')}</select></label><label>状态<select name="status">${['待处理','处理中','待回归','已关闭'].map(s=>`<option ${i.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>处理说明<textarea name="note" required></textarea></label><label>关联通过的回归尝试（可跨批次）<select name="regressionAttemptId"><option value="">尚未关联</option>${executionData().batches.flatMap(b=>b.attempts.map(a=>({...a,batchName:b.name}))).filter(a=>a.caseId===i.caseId&&a.result==='通过').map(a=>`<option value="${a.id}">${esc(a.batchName)} · ${esc(a.at)}</option>`).join('')}</select></label><label>不修复原因（无有效回归而关闭时必填）<textarea name="nonFixReason"></textarea></label>${i.history.map(h=>`<p>${esc(h.at)} · ${esc(h.status)} · ${esc(h.note)}</p>`).join('')}`,'保存处理',f=>{executionWrite('issue',{issueId:i.id,...Object.fromEntries(f)});return false})}
 return executionAct(action);
};
const executionRender=render;
render=function(){executionRender();if(page==='task'&&['execution','issues','summary'].includes(tab)&&!executionCache.has(taskId)&&!executionLoading&&!executionError)loadExecution()};
// Manual case maintenance is available without a model. AI-generated designs stay in their designer.
function manualCasesDialog(){const t=task();return modal('手工用例维护',`<p>适合已有用例录入或离线设计。已有 AI 用例请在测试设计中审阅；此处仅维护人工用例。</p><div class="actions">${btn('新增人工用例','manualCaseNew','primary small')}${btn('导出 CSV','caseCsvExport','small')}${btn('导入 CSV','caseCsvImport','small')}</div>${t.cases.filter(c=>c.origin==='manual').map(c=>`<div class="list-item row"><div><b>${esc(c.title)}</b><p>${c.confirmed?'已确认':'待确认'} · ${esc(c.priority)}</p></div>${btn('编辑','manualCaseEdit:'+c.id,'small')}</div>`).join('')||'<p>暂无人工用例。</p>'}`,'关闭',()=>{})}
function editManualCase(id){const t=task(),c=t.cases.find(c=>c.id===id)||{};return modal(id?'编辑人工用例':'新增人工用例',`<label>标题<input name="title" required maxlength="200" value="${esc(c.title||'')}"></label><div class="form-grid"><label>优先级<select name="priority">${['P0','P1','P2','P3'].map(x=>`<option ${x===(c.priority||'P1')?'selected':''}>${x}</option>`).join('')}</select></label><label>分层<select name="layer">${['手工','UI','API','端侧'].map(x=>`<option ${x===(c.layer||'手工')?'selected':''}>${x}</option>`).join('')}</select></label></div><label>需求 / 资料依据<input name="basis" required maxlength="1000" value="${esc(c.basis||'')}" placeholder="需求单号、规格章节及版本；未知规则请先澄清"></label><label>前置条件、测试数据、步骤与清理<textarea name="steps" required maxlength="10000">${esc(c.steps||'')}</textarea></label><label>预期结果<textarea name="expected" required maxlength="10000">${esc(c.expected||'')}</textarea></label><label class="inline-check"><input type="checkbox" class="check" name="confirmed">我已核对依据、步骤与预期，确认可执行</label><p class="subtitle">每次编辑都需重新确认。已创建批次中的快照不受修改影响。</p>`,'保存用例',f=>{if(!taskEditable(t)){toast('任务只读');return false}const entry={id:c.id||'MAN-'+crypto.randomUUID(),...Object.fromEntries(['title','priority','layer','basis','steps','expected'].map(k=>[k,String(f.get(k)).trim()])),origin:'manual',confirmed:f.get('confirmed')==='on',reviewNeeded:false,script:'未实现',revision:(c.revision||0)+1};if(!entry.title||!entry.basis||!entry.steps||!entry.expected){toast('请补齐必填内容');return false}if(c.id){(t.manualCaseHistory||=[]).push(structuredClone(c));Object.assign(c,entry)}else t.cases.push(entry);save();render();toast('人工用例已保存')})}
const manualAssets=assets;
assets=function(){return `<div class="card pad"><div class="row"><div><h2>人工用例</h2><p class="subtitle">不依赖模型。选择任务后录入或导入用例，审阅确认，再进入手工执行。</p></div>${btn('选择任务维护用例','manualCaseChoose','primary')}</div></div>`+manualAssets()};
const manualExecution=execution;
execution=function(){const h=manualExecution();return ['manual','issues','change'].includes(journey)?`<div class="actions" style="margin-bottom:16px">${btn('维护人工用例','manualCases','small')}</div>`+h:h};
const manualAct=act;
act=function(action){const [name,id]=action.split(':');
 if(name==='manualCaseChoose')return modal('选择任务',`<label>任务<select name="task">${data.tasks.filter(taskEditable).map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label>`,'维护用例',f=>{if(!f.get('task'))return false;taskId=f.get('task');closeModal();manualCasesDialog();return false});
 if(name==='manualCases')return manualCasesDialog();
 if(name==='manualCaseNew')return editManualCase();
 if(name==='manualCaseEdit')return editManualCase(id);
 if(name==='caseCsvExport'){const fields=['title','priority','layer','basis','steps','expected'];const quote=v=>{let text=String(v||'');if(/^[=+@\-\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'};download('manual-cases.csv','\ufeff'+[fields,...task().cases.map(c=>fields.map(k=>c[k]||''))].map(row=>row.map(quote).join(',')).join('\r\n'),'text/csv');return}
 if(name==='caseCsvImport')return modal('导入人工用例 CSV',`<p>UTF-8 CSV，表头：title,priority,layer,basis,steps,expected。所有导入用例均为待确认；不覆盖已有用例。</p><label>CSV 文件<input id="caseCsvFile" type="file" accept=".csv" required></label>`,'检查并预览',()=>{const file=$('#caseCsvFile').files[0];if(!file||file.size>1024*1024){toast('请选择不超过 1 MB 的 CSV');return false}file.text().then(text=>workspaceRequest('/api/cases/parse-csv',{text})).then(v=>{closeModal();modal('确认导入 '+v.cases.length+' 条用例',`<p>全部以待确认状态加入当前任务。</p><ul>${v.cases.map(c=>`<li>${esc(c.title)} · ${esc(c.priority)} · ${esc(c.layer)}</li>`).join('')}</ul>`,'加入待确认用例',()=>{if(!taskEditable(task())){toast('任务只读');return false}task().cases.push(...v.cases.map(c=>({...c,id:'MAN-'+crypto.randomUUID(),origin:'manual',confirmed:false,script:'未实现',revision:1})));save();render();toast('已导入，请逐条审阅')})}).catch(e=>toast(e.message));return false});
 return manualAct(action);
};
let executionOverview=null,overviewLoading=false,overviewError=false;
async function loadExecutionOverview(){if(overviewLoading)return;overviewLoading=true;overviewError=false;try{executionOverview=await workspaceRequest('/api/execution')}catch(e){overviewError=true;toast(e.message)}finally{overviewLoading=false;if(['reports','home'].includes(page))render()}}
const oldReports=reports;
reports=function(){return title('执行与报告','真实手工批次和冻结报告；历史示例记录独立保留。',btn('刷新列表','reportsRefresh','small'))+`<div class="card pad"><h2>冻结报告</h2>${(executionOverview?.reports||[]).filter(r=>data.tasks.some(t=>t.id===r.taskId&&taskLC(t).location!=='trash')).map(r=>`<div class="list-item row"><div><b>${esc(r.name)} · 修订 ${r.revision}</b><p>${esc(r.frozenAt)} · ${r.attemptCount} 次尝试</p><p>${Object.entries(r.counts).map(([k,v])=>esc(k)+' '+v).join(' / ')}</p></div>${btn('查看 / 导出','reportOpen:'+r.taskId+':'+r.id,'small')}</div>`).join('')||'<p>暂无冻结报告。</p>'}</div><details><summary>旧版任务报告与示例历史</summary>${oldReports()}</details>`};
function supportToolsPanel(){return `<div class="card pad"><h2>本地数据与诊断</h2><p>完整备份包含任务、模型产物、知识审阅、执行记录和证据，不包含 UI/API 运行环境及登录会话。</p><div class="actions">${btn('下载完整备份 ZIP','fullBackup','primary small')}${btn('查看诊断信息','diagnostics','small')}</div><p class="subtitle">恢复采用独立目录校验，不直接覆盖工作区。详见本轮实施说明。</p></div>`};
const supportAct=act;
act=function(action){const [name,tid,rid]=action.split(':');
 if(name==='reportsRefresh')return loadExecutionOverview();
 if(name==='reportOpen'){taskId=tid;return loadExecution(tid).then(()=>act('frozenView:'+rid))}
 if(name==='fullBackup')return flushWorkspace().then(async()=>{const r=await fetch('/api/backup',{cache:'no-store'});if(!r.ok)throw Error((await r.json()).error);const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='workbench-backup-'+new Date().toISOString().slice(0,10)+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}).catch(e=>toast(e.message));
 if(name==='diagnostics')return workspaceRequest('/api/diagnostics').then(v=>modal('本地工作台诊断',`<pre class="spec-preview">${esc(JSON.stringify(v,null,2))}</pre><p>自动化 not-connected 表示尚未接通真实执行器；不会输出伪通过。</p>`,'关闭',()=>{})).catch(e=>toast(e.message));
 return supportAct(action);
};
const supportRender=render;
render=function(){supportRender();if(page==='settings')$('#content').insertAdjacentHTML('afterbegin',supportToolsPanel());if(workspaceReady&&['reports','home'].includes(page)&&!executionOverview&&!overviewLoading&&!overviewError)loadExecutionOverview()};
const feedbackSummary=summary;
summary=function(){const d=executionData();return feedbackSummary()+`<div class="card pad"><div class="row"><div><h2>经验回馈知识</h2><p class="subtitle">从冻结报告提出候选，人工核对适用范围后采纳；不自动修改产品规格。</p></div>${btn('提出知识候选','feedbackNew','small')}</div>${(d.feedback||[]).map(f=>`<div class="list-item row"><div><b>${esc(f.title)}</b><p>${esc(f.status)} · ${esc(f.createdAt)}</p></div>${btn(f.status==='待审阅'?'审阅候选':'查看','feedbackReview:'+f.id,'small')}</div>`).join('')||'<p>暂无候选。</p>'}</div>`};
const feedbackAct=act;
act=function(action){const [name,id]=action.split(':');
 if(name==='feedbackNew'){const reports=executionData().reports;if(!reports.length)return toast('请先结束批次并冻结报告');return modal('提出知识候选',`<label>证据报告<select name="reportId">${reports.map(r=>`<option value="${r.id}">${esc(r.batch.name)} · 修订 ${r.revision}</option>`).join('')}</select></label><label>标题<input name="title" required maxlength="200"></label><label>建议沉淀的规则 / 测试经验<textarea name="content" required maxlength="10000"></textarea></label><label>证据、适用范围与限制<textarea name="basis" required maxlength="4000" placeholder="引用执行尝试/证据，说明适用版本；单次失败不能直接推断为产品规则。"></textarea></label>`,'保存候选',f=>{executionWrite('feedback',Object.fromEntries(f));return false})}
 if(name==='feedbackReview'){const p=executionData().feedback.find(x=>x.id===id);return modal('审阅知识候选',`<h3>${esc(p.title)}</h3><pre class="spec-preview">${esc(p.content)}\n\n依据与范围：${esc(p.basis)}\n报告：${esc(p.reportId)}</pre>${p.status==='待审阅'?'<label>结论<select name="decision"><option>已采纳</option><option>已拒绝</option></select></label><label>审阅说明<textarea name="note" required maxlength="4000"></textarea></label><p>采纳后写入工作台知识笔记目录，并可在选择规格时引用。不会修改 knowledge/product 原文件。</p>':`<p>${esc(p.status)} · ${esc(p.reviewNote)}</p>`}`,p.status==='待审阅'?'确认审阅':'关闭',f=>{if(p.status!=='待审阅')return;executionWrite('feedback-review',{id:p.id,...Object.fromEntries(f)}).then(v=>{if(v){knowledgeInfo=null;specCatalog=[]}});return false})}
 return feedbackAct(action);
};
// Browser-only automation history. Never invokes a product executor or changes design tasks.
const autoKey='healthmanager-automation-demo-v1';
let autoState;try{autoState=JSON.parse(localStorage.getItem(autoKey))}catch{}
if(!autoState||!Array.isArray(autoState.plans)||!Array.isArray(autoState.runs))autoState={plans:[],runs:[]};
let autoTab='quick',autoSource='sample',autoFeature='全部特性',autoLayer='全部',autoTier='smoke',autoQuery='',autoPicked=new Set(),autoEnvironment='',autoVersion='',autoMachine='本机',autoTrigger='手动',autoDetail='';
const autoSamples=[
 ['字段管理','创建文本字段','API','smoke','可示例'],['字段管理','创建后刷新持久化','UI','smoke','可示例'],
 ['字段管理','字段名长度边界','API','daily','可示例'],['视图管理/看板视图','切换看板分组','UI','daily','待实现'],
 ['导入导出/CSV 导入','导入有效 CSV','API','smoke','可示例'],['导入导出/CSV 导入','导入后查看数据','UI','smoke','可示例'],
 ['导入导出/CSV 导入','重复列名处理','API','daily','待复核'],['导入导出/CSV 导入','大文件异常提示','UI','full','已隔离']
].map((v,i)=>({id:'sample-'+i,feature:v[0],title:v[1],layer:v[2],tier:v[3],admission:v[4],version:'示例资产 v1',source:'合成示例资产'}));
function autoAssets(){return autoSource==='sample'?autoSamples:data.tasks.filter(t=>taskLC(t).location!=='trash').flatMap(t=>t.cases.map(c=>({id:t.id+'/'+c.id,title:c.title,feature:c.feature||'待维护特性归属',layer:['API','UI','性能','安全'].includes(c.layer)?c.layer:'未分类',tier:c.tier||'未分档',admission:c.reviewNeeded||!c.confirmed?'待复核':'未接入准入验证',version:String(c.revision||c.designJobId||'未标记版本'),source:t.name,taskId:t.id})));}
function autoFiltered(){return autoAssets().filter(c=>(autoFeature==='全部特性'||c.feature===autoFeature)&&(autoLayer==='全部'||c.layer===autoLayer)&&(autoTier==='all'||({smoke:['smoke'],daily:['smoke','daily'],full:['smoke','daily','full']}[autoTier]||[]).includes(c.tier))&&(!autoQuery||(c.title+' '+c.feature).includes(autoQuery)));}
function autoSave(){try{localStorage.setItem(autoKey,JSON.stringify(autoState));return true}catch{toast('浏览器存储失败，本次配置仅保留在内存');return false}}
function autoConfig(){return {source:autoSource,feature:autoFeature,layer:autoLayer,tier:autoTier,query:autoQuery,environment:autoEnvironment,productVersion:autoVersion,machine:autoMachine,trigger:autoTrigger,cases:structuredClone(autoAssets().filter(c=>autoPicked.has(c.id)))};}
function autoLoad(config){autoSource=config.source;autoFeature=config.feature;autoLayer=config.layer;autoTier=config.tier;autoQuery=config.query||'';autoEnvironment=config.environment;autoVersion=config.productVersion;autoMachine=config.machine;autoTrigger=config.trigger;autoPicked=new Set(config.cases.map(c=>c.id));autoTab='quick';page='automation';render();toast('已载入范围，请核对当前资产与版本');}
function autoSelect(label,id,values,current){return `<label>${label}<select id="${id}">${values.map(([v,n])=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`}
function automationPage(){return title('自动化执行','临时验证特性，或维护每日构建与冒烟计划。执行记录独立于测试设计任务。',btn('快速执行','autoTab:quick','primary'))+`<div class="notice info">本机旧版执行配置。可筛选范围、保存计划、检查条件并查看阻塞记录，不产生测试通过结果。此模块配置仅保存在当前浏览器，不进入正式工作区备份。</div><div class="tabs">${[['quick','快速执行'],['runs','运行记录'],['plans','执行计划'],['environments','执行环境']].map(([k,n])=>`<button type="button" class="${autoTab===k?'active':''}" data-action="autoTab:${k}">${n}</button>`).join('')}</div>`+({quick:autoQuick,runs:autoRuns,plans:autoPlans,environments:autoEnvironments}[autoTab])();}
function autoQuick(){const rows=autoFiltered(),chosen=autoAssets().filter(c=>autoPicked.has(c.id)),eligible=chosen.filter(c=>c.admission==='可示例');return `<div class="card pad"><h2>1. 选择特性和用例范围</h2><div class="form-grid">${autoSelect('资产来源','autoSource',[['sample','合成示例（体验筛选流程）'],['workspace','当前任务资产']],autoSource)}${autoSelect('特性目录','autoFeature',['全部特性',...new Set(autoAssets().map(c=>c.feature))].map(v=>[v,'多维表 / '+v]),autoFeature)}${autoSelect('自动化类型','autoLayer',[['全部','UI + 接口（组合）'],['UI','UI 自动化'],['API','接口自动化'],['性能','性能自动化'],['安全','安全自动化']],autoLayer)}${autoSelect('执行范围','autoTier',[['smoke','冒烟'],['daily','日构建（含冒烟）'],['full','全量（含日构建）'],['all','全部设计用例（含未分档）']],autoTier)}<label>搜索用例（回车应用）<input id="autoQuery" value="${esc(autoQuery)}" placeholder="用例名称或特性"></label></div><p class="subtitle">当前任务资产未建立可信脚本准入映射，不会把历史“已验证（示例）”当作真实可执行脚本。</p><div class="actions">${btn('选中当前筛选结果','autoSelectVisible','small')}${btn('清空选择','autoClear','link small')}</div></div><div class="card table-wrap"><table><thead><tr><th>选择</th><th>特性 / 用例</th><th>类型 / 档位</th><th>准入状态</th></tr></thead><tbody>${rows.map(c=>`<tr><td><input type="checkbox" class="check" data-auto-case="${esc(c.id)}" aria-label="选择 ${esc(c.title)}" ${autoPicked.has(c.id)?'checked':''}></td><td>${esc(c.title)}<small>${esc(c.feature)} · ${esc(c.source)} · ${esc(c.version)}</small></td><td>${esc(c.layer)} / ${esc(c.tier)}</td><td>${badge(c.admission)}</td></tr>`).join('')||`<tr><td colspan="4" class="empty">${['性能','安全'].includes(autoLayer)?autoLayer+'自动化暂未接入专项用例与执行器；不会将普通 UI/API 用例计入此分类。':'没有匹配用例；可选择“全部设计用例”查看未分档资产。'}</td></tr>`}</tbody></table></div><div class="card pad"><h2>2. 选择运行条件</h2><div class="form-grid"><label>测试环境<input id="autoEnvironment" value="${esc(autoEnvironment)}" placeholder="例如：basetest"></label><label>产品版本 / 构建号<input id="autoVersion" value="${esc(autoVersion)}" placeholder="明确填写本次部署版本"></label>${autoSelect('执行位置','autoMachine',[['本机','本机（未连接执行器）'],['CI电脑','CI 电脑（待配置）']],autoMachine)}${autoSelect('触发方式','autoTrigger',[['手动','手动'],['每日定时','每日定时（待接通调度）'],['构建完成后','构建完成后（待接通 CI）']],autoTrigger)}</div><p class="subtitle">UI 无人值守运行使用独立上下文；账号角色、资源隔离和清理策略将在执行前检查。定时或构建触发配置不会创建真实调度。</p></div><div class="card pad"><h2>3. 核对本次范围</h2><p>已选 ${chosen.length} 条 · 示例可用 ${eligible.length} 条 · 其余待处理 ${chosen.length-eligible.length} 条 · 真实可执行 <b>0</b> 条</p><p class="subtitle">修改筛选会清空选择，避免隐藏用例被意外执行。检查记录固定本次所选资产快照。</p><div class="actions">${btn('检查并运行','autoCheck','primary')}${btn('保存为执行计划','autoPlanSave','')}</div></div>`;}
function autoRuns(){const r=autoState.runs.find(r=>r.id===autoDetail);return `<div class="card pad"><h2>运行记录</h2><p class="subtitle">旧版记录只包含执行前阻塞。API 与 UI 分别展示检查结果。</p>${autoState.runs.slice().reverse().map(x=>`<div class="list-item row"><div><b>${esc(x.name)}</b><p>${esc(x.at)} · ${esc(x.config.productVersion)} · ${esc(x.config.environment)} · ${esc(x.config.layer)} · ${esc(x.config.trigger)}</p>${badge('执行前阻塞')} · 实际执行 0 / 选中 ${x.config.cases.length}</div>${btn('详情','autoRun:'+x.id,'small')}</div>`).join('')||'<div class="empty">暂无运行记录。从快速执行检查一次范围开始。</div>'}</div>`+(r?`<div class="card pad"><h2>${esc(r.name)}</h2><p>${esc(r.id)}${r.parentId?' · 来源运行 '+esc(r.parentId):''}</p>${r.checks.map(s=>`<p>• ${esc(s)}</p>`).join('')}<div class="form-grid">${['API','UI','性能','安全'].filter(layer=>['API','UI'].includes(layer)||r.config.layer===layer||r.config.cases.some(c=>c.layer===layer)).map(layer=>`<div class="source"><h3>${layer} 子项</h3>选中 ${r.config.cases.filter(c=>c.layer===layer).length} 条 · 执行 0 条 · ${r.config.cases.some(c=>c.layer===layer)?'执行器未连接':'本次未选择'}</div>`).join('')}</div><h3>固定用例范围</h3>${r.config.cases.map(c=>`<p>${esc(c.title)} · ${esc(c.version)} · ${esc(c.admission)}</p>`).join('')}<p>暂无测试日志、截图或清理证据，因为尚未启动产品测试。</p><div class="actions">${btn('载入相同范围','autoReuse:'+r.id,'small')}${btn('重跑失败项','autoRetry:'+r.id,'small')}</div></div>`:'');}
function autoPlans(){return `<div class="card pad"><h2>执行计划</h2><p>先选模板，核对特性、用例范围和环境，再保存。计划启停独立于测试任务生命周期。</p><div class="actions">${[['API','smoke','手动'],['UI','smoke','手动'],['API','daily','每日定时'],['UI','daily','每日定时'],['全部','full','构建完成后']].map((v,i)=>btn(v[0]+' '+({smoke:'冒烟',daily:'日构建',full:'全量'}[v[1]]),'autoTemplate:'+i,'small')).join('')}</div></div>${autoState.plans.map(p=>`<div class="card pad"><div class="row"><h3>${esc(p.name)}</h3>${badge(p.status)}</div><p>${esc(p.config.feature)} · ${esc(p.config.layer)} · ${esc(p.config.tier)} · ${p.config.cases.length} 条</p><p>${esc(p.config.trigger)} · ${esc(p.config.environment)} · ${esc(p.config.productVersion)}</p><p class="subtitle">调度未连接 · 下一次执行时间：未安排</p><div class="actions">${btn('载入并调整','autoPlanLoad:'+p.id,'small')}${btn(p.status==='已停用'?'恢复草稿':'停用','autoPlanToggle:'+p.id,'small')}</div></div>`).join('')||'<div class="card empty">暂无计划。快速执行中可以将选择的范围保存为计划。</div>'}`;}
function autoEnvironments(){return `<div class="grid">${['本机','CI 电脑'].map(n=>`<div class="card pad"><h2>${n}</h2>${badge('未连接')}<p>API 执行器：待接入</p><p>UI 执行器：待接入</p><p>账号角色与浏览器上下文：待配置</p><p>最近实际检查：尚未执行</p><p class="subtitle">${n==='本机'?'本机调试与无人值守 CI 上下文分别配置。':'首版通过现有 CI 或系统任务计划调用统一执行入口，不引入远程调度中间件。'}</p></div>`).join('')}</div>`;}
const automationAct=act;
act=function(action){const [name,id,tid]=action.split(':');
 if(name==='scenario'&&id==='regression'||name==='direct'&&id==='regression'){page='automation';autoTab='quick';render();return}
 if(name==='autoTab'){autoTab=id;autoDetail='';page='automation';render();return}
 if(name==='autoSelectVisible'){autoFiltered().forEach(c=>autoPicked.add(c.id));render();return}
 if(name==='autoClear'){autoPicked.clear();render();return}
 if(name==='autoTemplate'){const v=[['API','smoke','手动'],['UI','smoke','手动'],['API','daily','每日定时'],['UI','daily','每日定时'],['全部','full','构建完成后']][Number(id)];[autoLayer,autoTier,autoTrigger]=v;autoPicked.clear();autoTab='quick';render();return}
 if(name==='autoPlanSave'){const config=autoConfig();if(!config.cases.length||!config.environment.trim()||!config.productVersion.trim())return toast('请选择用例，并填写环境和产品构建版本');return modal('保存执行计划',`<label>计划名称<input name="name" required maxlength="100" placeholder="例如：CSV 导入每日回归"></label><p>保存为草稿。执行器和触发器未接通，不会自动开始运行。</p>`,'保存草稿',f=>{autoState.plans.push({id:crypto.randomUUID(),name:String(f.get('name')).trim(),status:'草稿',config,at:new Date().toISOString()});autoSave();autoTab='plans';render()})}
 if(name==='autoPlanLoad')return autoLoad(autoState.plans.find(p=>p.id===id).config);
 if(name==='autoPlanToggle'){const p=autoState.plans.find(p=>p.id===id);p.status=p.status==='已停用'?'草稿':'已停用';autoSave();render();return}
 if(name==='autoCheck'){const config=autoConfig();if(!config.cases.length||!config.environment.trim()||!config.productVersion.trim())return toast('请选择用例，并填写环境和产品构建版本');const checks=['执行器尚未连接，本次没有启动产品测试。',...(config.source==='sample'?['所选为合成示例资产，不能用于产品结论。']:['真实资产与脚本版本的准入映射尚未接通。']),...(config.cases.some(c=>c.admission!=='可示例')?['范围包含未实现、待复核或未准入用例，需先处理。']:[]),...(config.trigger!=='手动'?['触发方式仅为配置草稿，调度尚未接通。']:[])];const run={id:crypto.randomUUID(),name:config.feature+' · '+config.layer+' 检查',at:new Date().toISOString(),config,checks};autoState.runs.push(run);autoSave();autoDetail=run.id;autoTab='runs';render();return}
 if(name==='autoRun'){autoDetail=id;render();return}
 if(name==='autoReuse')return autoLoad(autoState.runs.find(r=>r.id===id).config);
 if(name==='autoRetry')return toast('本次没有真正执行，因此没有失败用例可重跑；请先接通执行器');
 if(name==='autoTask'){const t=data.tasks.find(t=>t.id===id);autoSource='workspace';autoFeature='全部特性';autoTier='all';autoLayer='全部';autoQuery='';autoPicked=new Set(autoAssets().filter(c=>c.taskId===t.id).map(c=>c.id));page='automation';autoTab='quick';render();return}
 return automationAct(action);
};
const automationRender=render;
render=function(){automationRender();if(page==='automation'){
 const fields={autoSource:v=>autoSource=v,autoFeature:v=>autoFeature=v,autoLayer:v=>autoLayer=v,autoTier:v=>autoTier=v,autoQuery:v=>autoQuery=v};
 Object.entries(fields).forEach(([id,set])=>{if($('#'+id))$('#'+id).onchange=e=>{set(e.target.value);autoPicked.clear();if(id==='autoSource')autoFeature='全部特性';render()}});
 [['autoEnvironment',v=>autoEnvironment=v],['autoVersion',v=>autoVersion=v],['autoMachine',v=>autoMachine=v],['autoTrigger',v=>autoTrigger=v]].forEach(([id,set])=>{if($('#'+id))$('#'+id).oninput=e=>set(e.target.value)});
 $$('[data-auto-case]').forEach(el=>el.onchange=()=>{el.checked?autoPicked.add(el.dataset.autoCase):autoPicked.delete(el.dataset.autoCase);render()});
 }
};
const autoPreviousJourney=enterJourney;
enterJourney=function(key,id,part){if(key==='regression'){return act('autoTask:'+id)}return autoPreviousJourney(key,id,part)};

