function envUrl(value,label,required=false,originOnly=false){if(!value){if(required)throw Error('请填写'+label);return ''}let u;try{u=new URL(value)}catch{throw Error(label+'不是有效 URL')}if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.hash)throw Error(label+'仅允许无凭据、无片段的 HTTP/HTTPS 地址');if(originOnly&&(u.pathname!=='/'||u.search))throw Error('站点根只能包含协议、域名和端口');return value.trim()}
function envEditor(id){const e=autoState.environments.find(e=>e.id===id)||{name:'',id:'',enabled:true,ui_enabled:true,api_enabled:false,base_url:'',origin:'',api_url:'',entry_mode:'wapp_direct',wapp_home_path:'/wapp/home',wapp_query:'',execution_mode:'ci_fresh_context',cdp_port:9333,features:{}};
return modal(id?'编辑执行环境':'新增执行环境',`<div class="form-grid"><label>环境标识<input name="id" required pattern="[a-zA-Z0-9_-]+" maxlength="64" value="${esc(e.id)}" ${id?'readonly':''}></label><label>显示名称<input name="name" required maxlength="100" value="${esc(e.name)}"></label></div><label class="inline-check"><input class="check" type="checkbox" name="enabled" ${e.enabled?'checked':''}>启用环境</label><label class="inline-check"><input class="check" type="checkbox" name="ui_enabled" ${e.ui_enabled?'checked':''}>支持 UI 自动化</label><label>UI 入口地址<input name="base_url" value="${esc(e.base_url)}" placeholder="https://host/wapp/home"></label><label>站点根地址（留空从入口推导）<input name="origin" value="${esc(e.origin)}"></label><label>入口模式<select name="entry_mode">${['wapp_direct','work_agent_shell'].map(v=>`<option ${e.entry_mode===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="form-grid"><label>Wapp 首页路径<input name="wapp_home_path" value="${esc(e.wapp_home_path)}"></label><label>Wapp 查询参数<input name="wapp_query" value="${esc(e.wapp_query)}" placeholder="hideMenu=2&workagent=true"></label></div><label>UI 执行模式<select name="execution_mode">${['ci_fresh_context','interactive_cdp'].map(v=>`<option ${e.execution_mode===v?'selected':''}>${v}</option>`).join('')}</select></label><label>本机 CDP 端口（仅交互模式使用）<input name="cdp_port" type="number" min="1" max="65535" value="${e.cdp_port}"></label><label class="inline-check"><input class="check" type="checkbox" name="api_enabled" ${e.api_enabled?'checked':''}>支持 API 自动化</label><label>API 基础地址<input name="api_url" value="${esc(e.api_url)}" placeholder="请填写真实 API 服务地址"></label><details><summary>环境能力（features）</summary><label>能力 JSON，仅布尔值<textarea name="features">${esc(JSON.stringify(e.features,null,2))}</textarea></label></details><p class="subtitle">保存仅校验配置格式，不访问产品服务。直连模式请勿使用 hideMenu=2，以免隐藏侧栏。</p>`,'保存环境',f=>{try{const raw=Object.fromEntries(f),key=raw.id.trim();if(!/^[A-Za-z0-9_-]{1,64}$/.test(key))throw Error('环境标识格式不正确');if(!id&&autoState.environments.some(x=>x.id.toLowerCase()===key.toLowerCase()))throw Error('环境标识已存在');const ui=f.has('ui_enabled'),api=f.has('api_enabled');if(!ui&&!api)throw Error('至少启用一种自动化类型');const base=envUrl(raw.base_url.trim(),'UI 入口',ui),apiUrl=envUrl(raw.api_url.trim(),'API 地址',api),origin=envUrl(raw.origin.trim()||(base?new URL(base).origin:''),'站点根',ui,true);const placeholder=[base,apiUrl].filter(Boolean).some(v=>new URL(v).hostname==='example.com'||new URL(v).hostname.endsWith('.example.com'));if(f.has('enabled')&&placeholder)throw Error('占位地址不能启用，请先填写实际地址');if(!raw.wapp_home_path.startsWith('/')||raw.wapp_home_path.startsWith('//'))throw Error('Wapp 路径应为 / 开头的站内路径');if(raw.entry_mode==='wapp_direct'&&new URLSearchParams(raw.wapp_query).get('hideMenu')==='2')throw Error('直连模式请移除 hideMenu=2');const features=JSON.parse(raw.features);if(!features||Array.isArray(features)||typeof features!=='object'||Object.values(features).some(v=>typeof v!=='boolean'))throw Error('features 必须是布尔值对象');const port=Number(raw.cdp_port);if(!Number.isInteger(port)||port<1||port>65535)throw Error('CDP 端口应为 1—65535');const next={id:key,name:raw.name.trim(),enabled:f.has('enabled'),ui_enabled:ui,api_enabled:api,base_url:base,api_url:apiUrl,origin,entry_mode:raw.entry_mode,wapp_home_path:raw.wapp_home_path,wapp_query:raw.wapp_query.replace(/^\?/,''),execution_mode:raw.execution_mode,cdp_port:port,features,placeholder,revision:(e.revision||0)+1,source:id?e.source:'工作台新增',updatedAt:new Date().toISOString()};if(id)autoState.environments[autoState.environments.indexOf(e)]=next;else autoState.environments.push(next);autoSave();render();toast('环境配置已保存')}catch(err){toast(err.message);return false}})}
const environmentAct=act;
act=function(action){const [name,id]=action.split(':');if(name==='envNew')return envEditor();if(name==='envEdit')return envEditor(id);if(name==='envToggle'){const e=autoState.environments.find(x=>x.id===id);if(!e.enabled&&e.placeholder)return toast('请先编辑占位地址');e.enabled=!e.enabled;e.revision++;autoSave();render();return}if(name==='envChoose'){const e=autoState.environments.find(x=>x.id===id);if(!e.enabled||e.placeholder)return toast('请选择已启用的有效环境');autoEnvironment=id;autoTab='quick';render();return}if(['autoCheck','autoPlanSave'].includes(name)){const issue=autoEnvIssue();if(issue)return toast(issue)}return environmentAct(action)};
const environmentRender=render;
