const environmentRuns=autoRuns;
autoRuns=function(){const r=autoState.runs.find(x=>x.id===autoDetail),e=r?.config.environmentSnapshot;return environmentRuns()+(e?`<div class="card pad"><h3>本次环境快照</h3><p>${esc(e.name)} · ${esc(e.id)} · 修订 ${e.revision}</p><p>UI：${esc(e.base_url||'未配置')}</p><p>API：${esc(e.api_url||'未配置')}</p><p>站点根：${esc(e.origin)} · ${esc(e.entry_mode)} · ${esc(e.execution_mode)}</p><p class="subtitle">修改或停用环境不会改变这条历史记录；再次载入时会检查当前配置。</p></div>`:'')};
