const assetBoardKey='healthmanager-asset-board-v1';let abPrefs;try{abPrefs=JSON.parse(localStorage.getItem(assetBoardKey))}catch{}
const abProducts=['健康管理'];
function abProductName(value){const name=String(value||'').trim();return /^(clouddoc|云文档|welink云文档)$/i.test(name)?'健康管理':name||'未归属'}
function abLayer(r){return String(r.c.layer||'').trim().toUpperCase()}
if(!abPrefs||typeof abPrefs!=='object')abPrefs={};abPrefs={mapping:{},features:[],...abPrefs};
abPrefs.features=abPrefs.features.map(f=>({...f,product:abProductName(f.product)}));
let abTab='overview';
let abProduct='',abVersion='',abFeature='',abFocus='all',abSearch='',abShowSamples=false,abSort='risk';
function abSave(){try{localStorage.setItem(assetBoardKey,JSON.stringify(abPrefs))}catch{toast('看板归属保存失败，请检查浏览器存储')}}
function abRows(){const map=new Map();for(const t of data.tasks.filter(t=>taskLC(t).location!=='trash'&&(!abVersion||t.version===abVersion))){
 const candidate=!t.cases.length&&t.caseDesigner?.draft?.cases?.length;const cases=candidate?t.caseDesigner.draft.cases:t.cases;
 for(const c of cases||[]){if(c.status==='已失效'||c.retired)continue;const key=c.assetId||t.id+'/'+(candidate?'candidate/':'')+c.id;const meta=abPrefs.mapping[key]||{},sample=!!c.isDemo||(/示例|模拟/.test(c.script||''))||(t.id==='TASK-001'&&/^TC-00[1-4]$/.test(c.id));if(!abShowSamples&&sample)continue;
 const row={key,c,t,candidate:!!candidate,sample,product:abProductName(meta.product||c.product||t.product),feature:meta.feature||c.feature||t.feature||'待维护特性',confirmed:!candidate&&!!c.confirmed&&!c.reviewNeeded,review:!!c.reviewNeeded,applicability:meta.applicability||c.automationApplicability||'未评估',sources:[t],duplicate:false};
 if(map.has(key)){const old=map.get(key);old.sources.push(t);old.duplicate=true;old.confirmed=old.confirmed&&row.confirmed;old.review=old.review||row.review;if(JSON.stringify(old.c.steps)!==JSON.stringify(row.c.steps)||JSON.stringify(old.c.expected)!==JSON.stringify(row.c.expected)){old.review=true;old.confirmed=false;}}
 else map.set(key,row);
 }}return [...map.values()]}
function abScope(){return abRows().filter(r=>(!abProduct||r.product===abProduct)&&(!abFeature||r.feature===abFeature)&&(!abVersion||r.sources.some(t=>t.version===abVersion))&&(!abSearch||(r.c.title+' '+r.feature+' '+r.sources.map(t=>t.requirementNo).join(' ')).toLowerCase().includes(abSearch.toLowerCase())))}
function abMetrics(rows){return {total:rows.length,confirmed:rows.filter(r=>r.confirmed).length,pending:rows.filter(r=>!r.confirmed).length,review:rows.filter(r=>r.review).length,eligible:rows.filter(r=>r.confirmed&&r.applicability==='适合自动化').length,unknown:rows.filter(r=>r.applicability==='未评估').length,high:rows.filter(r=>['P0','P1'].includes(r.c.priority)&&r.confirmed&&r.applicability==='适合自动化').length,unassigned:rows.filter(r=>r.product==='未归属'||r.feature==='待维护特性').length}}
function abMatches(r){return abFocus==='all'||abFocus==='pending'&&!r.confirmed||abFocus==='review'&&r.review||abFocus==='eligible'&&r.confirmed&&r.applicability==='适合自动化'||abFocus==='unknown'&&r.applicability==='未评估'||abFocus==='unassigned'&&(r.product==='未归属'||r.feature==='待维护特性')||abFocus==='high'&&['P0','P1'].includes(r.c.priority)&&r.confirmed&&r.applicability==='适合自动化'}
function abPercent(n,d){return d?Math.round(n/d*100)+'%':'—'}
function abGroupAction(product,feature=''){return 'abGroup:'+encodeURIComponent(JSON.stringify([product,feature]))}
function abCards(allProducts=false){const rows=abRows();return `<div class="ab-product-grid">${abProducts.filter(p=>allProducts||!abProduct||p===abProduct).map(p=>{const list=rows.filter(r=>r.product===p),m=abMetrics(list);return `<article class="card pad ab-product"><div class="row"><h2>${esc(p)}</h2>${btn('查看用例',abGroupAction(p),'small')}</div><div class="ab-layer-counts">${['UI','API'].map(layer=>`<button data-action="abLayer:${encodeURIComponent(JSON.stringify([p,layer]))}"><span>${layer} 用例</span><strong>${list.filter(r=>abLayer(r)===layer).length}</strong><small>查看用例 →</small></button>`).join('')}</div><div class="ab-numbers"><span>全部用例 <b>${m.total}</b></span><span>已确认 <b>${m.confirmed}</b></span><span>其他 / 未分类 <b>${list.filter(r=>!['UI','API'].includes(abLayer(r))).length}</b></span></div><p class="subtitle">${m.total?'按当前任务用例去重统计，含待确认用例。':'尚无已关联的用例，请导入或维护产品归属。'}</p></article>`}).join('')}</div>`}
function abMatrix(){const rows=abScope();const groups=new Map();for(const f of abPrefs.features)if(!abProduct||f.product===abProduct)groups.set(f.product+'\n'+f.feature,{...f,rows:[]});for(const r of rows){const key=r.product+'\n'+r.feature;if(!groups.has(key))groups.set(key,{product:r.product,feature:r.feature,rows:[]});groups.get(key).rows.push(r)}const list=[...groups.values()].filter(g=>!abFeature||g.feature===abFeature).sort((a,b)=>abSort==='name'?(a.product+a.feature).localeCompare(b.product+b.feature,'zh-CN'):abMetrics(b.rows).review-abMetrics(a.rows).review||abMetrics(b.rows).pending-abMetrics(a.rows).pending);return `<div class="card"><div class="card-head"><div><h2>特性覆盖矩阵</h2><p class="subtitle">零用例特性也保留；当前版本筛选下的零值表示未找到关联资产。</p></div>${btn('维护特性目录','abFeatureNew','small')}</div><div class="table-wrap"><table><thead><tr><th>产品 / 特性</th><th>设计</th><th>已确认</th><th>待确认 / 复核</th><th>适合自动化</th><th>已自动化</th><th>关注点</th></tr></thead><tbody>${list.map(g=>{const m=abMetrics(g.rows);return `<tr><td>${btn(g.feature,abGroupAction(g.product,g.feature),'link')}<small>${esc(g.product)}</small></td><td>${m.total}</td><td>${m.confirmed}</td><td>${m.pending} / ${m.review}</td><td>${m.eligible}</td><td>—</td><td>${!m.total?'尚无用例':m.review?'需求变化待复核':m.unknown?'适用性待评估':'准入数据待接入'}</td></tr>`}).join('')}</tbody></table></div></div>`}
function abDetailPage(){const rows=abScope(),m=abMetrics(rows),matched=rows.filter(abMatches),details=matched.slice(abPage*50,abPage*50+50);return `<div class="card pad ab-filters"><label>产品<select id="abProduct"><option value="">全部产品</option>${[...new Set([...abProducts,...abPrefs.features.map(f=>f.product),...abRows().map(r=>r.product)])].map(p=>`<option ${abProduct===p?'selected':''}>${esc(p)}</option>`).join('')}</select></label><label>适用产品版本<select id="abVersion"><option value="">全部版本</option>${[...new Set(data.tasks.map(t=>t.version).filter(Boolean))].map(v=>`<option ${abVersion===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>搜索<input id="abSearch" value="${esc(abSearch)}" placeholder="用例、特性、需求单号 · 回车"></label><label>矩阵排序<select id="abSort"><option value="risk" ${abSort==='risk'?'selected':''}>待复核优先</option><option value="name" ${abSort==='name'?'selected':''}>产品 / 特性名称</option></select></label><label class="inline-check"><input id="abShowSamples" class="check" type="checkbox" ${abShowSamples?'checked':''}>包含示例资产</label>${btn('清空筛选','abReset','link small')}</div><div class="notice info">本地 UI 资产已读取静态准入状态；静态可执行不代表当前环境回放通过。设计用例与脚本尚未建立完整关联，自动化覆盖率暂不计算。缺少产品归属的用例显示“未归属”，可逐项维护。本机归属与适用性评估仅在本浏览器使用，不进入后台备份。</div><div class="ab-kpis">${[['设计用例',m.total,'all'],['已确认',m.confirmed,'confirmed'],['待确认 / 复核',m.pending,'pending'],['已自动化','—','admitted'],['自动化覆盖率','—','coverage']].map(([label,n,k])=>`<button class="card pad" type="button" data-action="abFocus:${k}"><span>${label}</span><strong>${n}</strong></button>`).join('')}</div>${abMatrix()}<div class="card pad"><h2>优先处理</h2><div class="actions">${btn('需求变化待复核 '+m.review,'abFocus:review','small')}${btn('P0/P1 自动化状态待核实 '+m.high,'abFocus:high','small')}${btn('适用性未评估 '+m.unknown,'abFocus:unknown','small')}${btn('归属待补齐 '+m.unassigned,'abFocus:unassigned','small')}</div><p class="subtitle">未接通准入前，“待核实”不等于已确认缺少脚本。卡片按产品与版本统计；下表进一步应用特性、搜索和缺口筛选。</p></div><div class="card" id="abDetails"><div class="card-head"><div><h2>用例明细 · ${matched.length}</h2><div class="actions">${btn('上一页','abPage:prev','small')}${Math.min(abPage+1,Math.max(1,Math.ceil(matched.length/50)))} / ${Math.max(1,Math.ceil(matched.length/50))}${btn('下一页','abPage:next','small')}</div><p>${esc(abProduct||'全部产品')} / ${esc(abFeature||'全部特性')} · ${esc(({UI:'UI 用例',API:'API 用例',all:'全部',confirmed:'已确认',pending:'待确认 / 复核',review:'待复核',eligible:'适合自动化',unknown:'适用性待评估',high:'P0/P1 自动化待核实',unassigned:'归属待补齐'})[abFocus]||'全部')}</p></div>${btn('查看全部明细','abFocus:all','small')}</div><div class="table-wrap"><table><thead><tr><th>用例与来源</th><th>产品 / 特性</th><th>优先级 / 测试层</th><th>设计 / 脚本状态</th><th>自动化适用性</th><th>操作</th></tr></thead><tbody>${details.map(r=>`<tr><td>${esc(r.c.title)}<small>${esc(r.c.id)} · ${r.candidate?'模型候选 · ':''}${r.sample?'示例 · ':''}${esc(r.sources.map(t=>t.name).join('、'))}</small>${r.duplicate?'<small>共享 ID 已去重；来源版本差异需复核</small>':''}</td><td>${esc(r.product)}<small>${esc(r.feature)}</small></td><td>${esc(r.c.priority||'未分级')} / ${esc(r.c.layer||'未分类')}</td><td>${badge(r.local?r.c.admission:r.review?'待复核':r.confirmed?'已确认':'待确认')}</td><td>${esc(r.applicability)}<small>${r.local?esc(r.c.suiteTier)+' · '+esc(r.c.reason):'实现准入：待接入'}</small></td><td>${r.local?btn('查看规格与脚本','abInspect:'+encodeURIComponent(r.key),'small'):btn('维护归属','abEdit:'+encodeURIComponent(r.key),'small')+btn('查看任务','open:'+r.t.id,'link small')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">此范围暂无用例。</td></tr>'}</tbody></table></div></div><details class="card pad"><summary>统计口径与当前边界</summary><p>本地 UI 用例按产品绑定路径统计；工作台设计资产只统计未移入回收站任务的当前用例；无落地用例时展示模型候选并标注。assetId 相同的资产去重；没有共享 ID 时按来源任务和用例 ID 计数，不按标题猜测同一用例。历史归档修订不重复计入。API/UI 是测试层，手工是执行方式；历史混合标签列为“其他”，待维护。</p><p>未接入完整需求分母、正式准入与有效执行结果，因此不展示虚假的需求覆盖、通过率或趋势。预置特性是可维护的展示目录，不表示已有用例覆盖。</p></details>`};
function abOverviewPage(){const rows=abRows(),unassigned=rows.filter(r=>!abProducts.includes(r.product)).length;return `<div class="card pad ab-overview-filters"><label>适用产品版本<select id="abVersion"><option value="">全部版本</option>${[...new Set(data.tasks.map(t=>t.version).filter(Boolean))].map(v=>`<option ${abVersion===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label class="inline-check"><input id="abShowSamples" class="check" type="checkbox" ${abShowSamples?'checked':''}>包含示例资产</label></div>${abCards(true)}<p class="subtitle">按当前任务的有效用例去重统计，含待确认用例；UI/API 数量不代表已实现自动化。点击数字进入「用例明细」。${unassigned?`另有 ${unassigned} 条用例尚未归入这三个产品，请在用例明细中维护归属。`:''}</p>`}
assets=function(){return title('测试资产',abTab==='overview'?'按产品查看 UI / API 用例规模。':'筛选用例、查看特性覆盖并维护资产归属。',abTab==='details'?btn('维护人工用例','manualCaseChoose','primary'):'')+`<div class="tabs ab-tabs" role="tablist" aria-label="测试资产视图">${[['overview','产品用例总览'],['details','用例明细']].map(([key,label])=>`<button role="tab" aria-selected="${abTab===key}" class="${abTab===key?'active':''}" data-action="abTab:${key}">${label}</button>`).join('')}</div><section role="tabpanel" aria-label="${abTab==='overview'?'产品用例总览':'用例明细'}">${abTab==='overview'?abOverviewPage():abDetailPage()}</section>`};
const abPreviousMatch=abMatches;
abMatches=function(r){return ['UI','API'].includes(abFocus)?abLayer(r)===abFocus:abFocus==='confirmed'?r.confirmed:abPreviousMatch(r)};
const abOriginalAct=act;
act=function(action){const [name,arg]=action.split(':');if(name==='abTab'){abTab=arg==='details'?'details':'overview';render();return}if(name==='abLayer'){abTab='details';[abProduct,abFocus]=JSON.parse(decodeURIComponent(arg));abFeature='';abSearch='';render();$('#abDetails')?.scrollIntoView({block:'start',behavior:'smooth'});return}if(name==='abFocus'){if(['admitted','coverage'].includes(arg))return toast('自动化准入尚未接通，暂不能计算此指标');abTab='details';abFocus=arg;render();$('#abDetails')?.scrollIntoView({block:'start',behavior:'smooth'});return}if(name==='abGroup'){abTab='details';abSearch='';[abProduct,abFeature]=JSON.parse(decodeURIComponent(arg));abFocus='all';render();return}if(name==='abReset'){abProduct='';abVersion='';abFeature='';abSearch='';abFocus='all';render();return}
 if(name==='abEdit'){const key=decodeURIComponent(arg),r=abRows().find(r=>r.key===key);return modal('维护用例归属与适用性',`<h3>${esc(r.c.title)}</h3><label>产品<input name="product" required maxlength="100" value="${esc(r.product==='未归属'?'':r.product)}" list="abProductNames"><datalist id="abProductNames">${abProducts.map(p=>`<option value="${esc(p)}">`).join('')}</datalist></label><label>特性路径<input name="feature" required maxlength="200" value="${esc(r.feature==='待维护特性'?'':r.feature)}" placeholder="多维表/字段管理"></label><label>自动化适用性<select name="applicability">${['未评估','适合自动化','不适合自动化'].map(x=>`<option ${r.applicability===x?'selected':''}>${x}</option>`).join('')}</select></label><p>此处评估适用性，不授予脚本准入，也不修改设计确认状态。</p>`,'保存',f=>{const meta=Object.fromEntries(f);meta.product=abProductName(meta.product);meta.feature=meta.feature.trim();if(!meta.product||!meta.feature)return false;abPrefs.mapping[key]=meta;if(!abPrefs.features.some(x=>x.product===meta.product&&x.feature===meta.feature))abPrefs.features.push({product:meta.product,feature:meta.feature});abSave();render()})}
 if(name==='abFeatureNew')return modal('新增特性目录','<label>产品<input name="product" required maxlength="100"></label><label>特性路径<input name="feature" required maxlength="200" placeholder="多维表/字段管理"></label><p>没有用例的特性也会显示在矩阵中。</p>','保存',f=>{const product=abProductName(f.get('product')),feature=f.get('feature').trim();if(!product||!feature)return false;if(abPrefs.features.some(x=>x.product===product&&x.feature===feature)){toast('该特性已存在');return false}abPrefs.features.push({product,feature});abSave();render()});return abOriginalAct(action)};
const abOriginalRender=render;
render=function(){abOriginalRender();if(page!=='assets')return;for(const [id,set] of [['abProduct',v=>{abProduct=v;abFeature=''}],['abVersion',v=>abVersion=v],['abSort',v=>abSort=v]])if($('#'+id))$('#'+id).onchange=e=>{set(e.target.value);render()};if($('#abShowSamples'))$('#abShowSamples').onchange=e=>{abShowSamples=e.target.checked;render()};if($('#abSearch'))$('#abSearch').onkeydown=e=>{if(e.key==='Enter'){abSearch=e.target.value;abFeature='';render()}}};
